{"path":"test_chip8.mjs","content":"import fs from 'fs';
import vm from 'vm';

const html = fs.readFileSync('chip8_openrouter-moonshotai-kimi-k3_01.html', 'utf8');
const m = html.match(/<script>([\s\S]*?)<\/script>/);
if (!m) { console.error('no script tag'); process.exit(1); }
const code = m[1];

// --- minimal DOM stubs so the whole script (UI wiring included) runs ---
const elStub = () => ({
  addEventListener() {}, appendChild() {}, classList: { add() {}, remove() {} },
  textContent: '', value: '10', id: '', files: [],
  getContext: () => ({ fillRect() {}, set fillStyle(v) {} }),
  width: 640, height: 320
});
const sandbox = {
  console, Uint8Array, Math,
  document: { getElementById: elStub, createElement: elStub },
  window: { addEventListener() {} },
  requestAnimationFrame() {},
  FileReader: function () {},
};
vm.createContext(sandbox);
vm.runInContext(code, sandbox);

const Chip8 = vm.runInContext('Chip8', sandbox);
const DEMO_ROM = vm.runInContext('DEMO_ROM', sandbox);

let pass = 0, fail = 0;
const ok = (name, cond) => { if (cond) pass++; else { fail++; console.log('FAIL:', name); } };

// DEMO_ROM bytes match hand-assembled spec
const spec = [0x60,0x1C,0x61,0x0E,0x63,0x01,0x00,0xE0,0xA2,0x2E,0xD0,0x15,
  0x62,0x07,0xE2,0x9E,0x12,0x14,0x80,0x35, 0x62,0x09,0xE2,0x9E,0x12,0x1C,0x80,0x34,
  0x62,0x05,0xE2,0x9E,0x12,0x24,0x81,0x35, 0x62,0x08,0xE2,0x9E,0x12,0x2C,0x81,0x34,
  0x12,0x06, 0x20,0x70,0xF8,0x70,0x20];
ok('DEMO_ROM bytes match spec', DEMO_ROM.length === spec.length && spec.every((b, i) => DEMO_ROM[i] === b));

// helper: fresh chip with a tiny program
function chipWith(bytes) {
  const c = new Chip8();
  c.loadRom(new Uint8Array(bytes));
  return c;
}

// --- font at 0x050 ---
{
  const c = new Chip8();
  ok('font 0 at 0x050', c.memory[0x050] === 0xF0 && c.memory[0x054] === 0xF0);
  ok('font F at 0x09B', c.memory[0x050 + 15 * 5] === 0xF0 && c.memory[0x050 + 15 * 5 + 4] === 0x80);
}

// --- 00E0 CLS ---
{
  const c = chipWith([0x00, 0xE0]);
  c.display[100] = 1; c.cycle();
  ok('00E0 CLS', c.display[100] === 0 && c.drawFlag === true);
}

// --- 1nnn JP ---
{
  const c = chipWith([0x12, 0x34]);
  c.cycle();
  ok('1nnn JP', c.pc === 0x234);
}

// --- 2nnn CALL / 00EE RET ---
{
  const c = chipWith([0x22, 0x08, 0x00, 0x00, 0x00, 0x00, 0x00, 0xEE]);
  c.cycle(); // CALL 0x208
  ok('2nnn CALL', c.pc === 0x208 && c.stack.length === 1 && c.stack[0] === 0x202);
  c.cycle(); // RET
  ok('00EE RET', c.pc === 0x202 && c.stack.length === 0);
}

// --- 3xnn SE ---
{
  const c = chipWith([0x60, 0x42, 0x30, 0x42]);
  c.cycle(); c.cycle();
  ok('3xnn SE taken', c.pc === 0x206);
  const c2 = chipWith([0x60, 0x41, 0x30, 0x42]);
  c2.cycle(); c2.cycle();
  ok('3xnn SE not taken', c2.pc === 0x204);
}

// --- 4xnn SNE ---
{
  const c = chipWith([0x60, 0x41, 0x40, 0x42]);
  c.cycle(); c.cycle();
  ok('4xnn SNE taken', c.pc === 0x206);
  const c2 = chipWith([0x60, 0x42, 0x40, 0x42]);
  c2.cycle(); c2.cycle();
  ok('4xnn SNE not taken', c2.pc === 0x204);
}

// --- 5xy0 SE ---
{
  const c = chipWith([0x60, 0x07, 0x61, 0x07, 0x50, 0x10]);
  c.cycle(); c.cycle(); c.cycle();
  ok('5xy0 SE taken', c.pc === 0x208);
  const c2 = chipWith([0x60, 0x07, 0x61, 0x08, 0x50, 0x10]);
  c2.cycle(); c2.cycle(); c2.cycle();
  ok('5xy0 SE not taken', c2.pc === 0x206);
}

// --- 6xnn LD / 7xnn ADD ---
{
  const c = chipWith([0x6A, 0xFF, 0x7A, 0x02]);
  c.cycle(); c.cycle();
  ok('6xnn LD + 7xnn ADD wrap', c.v[0xA] === 0x01);
}

// --- 8xy0 LD ---
{
  const c = chipWith([0x60, 0x55, 0x61, 0xAA, 0x80, 0x10]);
  c.cycle(); c.cycle(); c.cycle();
  ok('8xy0 LD', c.v[0] === 0xAA);
}

// --- 8xy1/2/3 OR/AND/XOR ---
{
  const c = chipWith([0x60, 0xF0, 0x61, 0x0F, 0x80, 0x11, 0x80, 0x12, 0x80, 0x13]);
  c.cycle(); c.cycle();
  c.cycle(); ok('8xy1 OR', c.v[0] === 0xFF);
  c.v[0] = 0xF0; c.cycle(); ok('8xy2 AND', c.v[0] === 0x00);
  c.v[0] = 0xF0; c.cycle(); ok('8xy3 XOR', c.v[0] === 0xFF);
}

// --- 8xy4 ADD carry ---
{
  const c = chipWith([0x60, 0xC8, 0x61, 0xC8, 0x80, 0x14]);
  c.cycle(); c.cycle(); c.cycle();
  ok('8xy4 carry', c.v[0] === 0x90 && c.v[0xF] === 1);
  const c2 = chipWith([0x60, 0x10, 0x61, 0x20, 0x80, 0x14]);
  c2.cycle(); c2.cycle(); c2.cycle();
  ok('8xy4 no carry', c2.v[0] === 0x30 && c2.v[0xF] === 0);
}

// --- 8xy5 SUB borrow ---
{
  const c = chipWith([0x60, 0x10, 0x61, 0x20, 0x80, 0x15]);
  c.cycle(); c.cycle(); c.cycle();
  ok('8xy5 borrow', c.v[0] === 0xF0 && c.v[0xF] === 0);
  const c2 = chipWith([0x60, 0x20, 0x61, 0x10, 0x80, 0x15]);
  c2.cycle(); c2.cycle(); c2.cycle();
  ok('8xy5 no borrow', c2.v[0] === 0x10 && c2.v[0xF] === 1);
}

// --- 8xy6 SHR ---
{
  const c = chipWith([0x60, 0x03, 0x80, 0x06]);
  c.cycle(); c.cycle();
  ok('8xy6 SHR', c.v[0] === 0x01 && c.v[0xF] === 1);
  const c2 = chipWith([0x60, 0x04, 0x80, 0x06]);
  c2.cycle(); c2.cycle();
  ok('8xy6 SHR lsb0', c2.v[0] === 0x02 && c2.v[0xF] === 0);
}

// --- 8xy7 SUBN ---
{
  const c = chipWith([0x60, 0x10, 0x61, 0x20, 0x80, 0x17]);
  c.cycle(); c.cycle(); c.cycle();
  ok('8xy7 SUBN', c.v[0] === 0x10 && c.v[0xF] === 1);
  const c2 = chipWith([0x60, 0x20, 0x61, 0x10, 0x80, 0x17]);
  c2.cycle(); c2.cycle(); c2.cycle();
  ok('8xy7 SUBN borrow', c2.v[0] === 0xF0 && c2.v[0xF] === 0);
}

// --- 8xyE SHL ---
{
  const c = chipWith([0x60, 0x81, 0x80, 0x0E]);
  c.cycle(); c.cycle();
  ok('8xyE SHL', c.v[0] === 0x02 && c.v[0xF] === 1);
  const c2 = chipWith([0x60, 0x41, 0x80, 0x0E]);
  c2.cycle(); c2.cycle();
  ok('8xyE SHL msb0', c2.v[0] === 0x82 && c2.v[0xF] === 0);
}

// --- 9xy0 SNE ---
{
  const c = chipWith([0x60, 0x07, 0x61, 0x08, 0x90, 0x10]);
  c.cycle(); c.cycle(); c.cycle();
  ok('9xy0 SNE taken', c.pc === 0x208);
  const c2 = chipWith([0x60, 0x07, 0x61, 0x07, 0x90, 0x10]);
  c2.cycle(); c2.cycle(); c2.cycle();
  ok('9xy0 SNE not taken', c2.pc === 0x206);
}

// --- Annn LD I / Bnnn JP V0 ---
{
  const c = chipWith([0xA3, 0x00]);
  c.cycle();
  ok('Annn LD I', c.I === 0x300);
  const c2 = chipWith([0x60, 0x04, 0xB2, 0x00]);
  c2.cycle(); c2.cycle();
  ok('Bnnn JP V0', c2.pc === 0x204);
}

// --- Cxnn RND mask ---
{
  const c = chipWith([0xC0, 0x0F]);
  let inRange = true;
  for (let i = 0; i < 200; i++) { const cc = chipWith([0xC0, 0x0F]); cc.cycle(); if (cc.v[0] > 0x0F) inRange = false; }
  ok('Cxnn RND mask', inRange);
}

// --- Dxyn DRW xor + collision ---
{
  // sprite 1 byte 0xFF at I=0x210, draw at (0,0) twice -> collision on 2nd
  const c = chipWith([0xA2, 0x10, 0x60, 0x00, 0x61, 0x00, 0xD0, 0x01, 0xD0, 0x01]);
  c.memory[0x210] = 0xFF;
  c.cycle(); c.cycle(); c.cycle();
  c.cycle(); // first draw
  ok('DRW draws 8 px', c.display[0] === 1 && c.display[7] === 1 && c.v[0xF] === 0);
  c.cycle(); // second draw -> xor off, collision
  ok('DRW xor+collision', c.display[0] === 0 && c.v[0xF] === 1);
}

// --- Ex9E SKP / ExA1 SKNP ---
{
  const c = chipWith([0x60, 0x05, 0xE0, 0x9E]);
  c.cycle(); c.keys[5] = 1; c.cycle();
  ok('Ex9E SKP pressed', c.pc === 0x206);
  const c2 = chipWith([0x60, 0x05, 0xE0, 0x9E]);
  c2.cycle(); c2.cycle();
  ok('Ex9E SKP not pressed', c2.pc === 0x204);
  const c3 = chipWith([0x60, 0x05, 0xE0, 0xA1]);
  c3.cycle(); c3.cycle();
  ok('ExA1 SKNP not pressed', c3.pc === 0x206);
  const c4 = chipWith([0x60, 0x05, 0xE0, 0xA1]);
  c4.cycle(); c4.keys[5] = 1; c4.cycle();
  ok('ExA1 SKNP pressed', c4.pc === 0x204);
}

// --- Fx07 / Fx15 / Fx18 timers ---
{
  const c = chipWith([0x60, 0x05, 0xF0, 0x15, 0xF0, 0x18, 0xF1, 0x07]);
  c.cycle(); c.cycle(); c.cycle();
  ok('Fx15/Fx18 set timers', c.delayTimer === 5 && c.soundTimer === 5);
  c.tickTimers();
  ok('timers tick down', c.delayTimer === 4 && c.soundTimer === 4);
  c.cycle(); // Fx07 read DT into V1
  ok('Fx07 read DT', c.v[1] === 4);
}

// --- Fx0A blocking key wait ---
{
